        self._list = list
        self._type = None

        self.value = value
        if isinstance(value, str):
            self.key = value
            self._type = "subject"
        elif isinstance(value, dict):
            self.key = value["key"]
            self.value = self._list._site.get(self.key) if hasattr(self._list, "_site") else value
        else:
            self.key = value.key

